import { PrelimControls, PrelimResults } from './PrelimControls.jsx';
import { useState, useMemo, useId } from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { MATERIALS } from './engineering-data.js';
import { PRODUCTS } from './products.js';
import { DEFAULT_INPUTS, evaluateDesign } from './design-state.js';
import { generateReportHTML } from './report.js';
import QuoteWorkbench from './quoting/QuoteWorkbench.jsx';
import { newSession, loadProject } from './quoting/project.js';

const JWT_LOGO = "data:image/png;base64,";

function VesselSVG({ vessel, product, sizing, supportType = "skirt" }) {
  if (!vessel) return null;
  const { D_ID, shellLength, headDepthID, isPipe, nozzles } = vessel;
  const isBuffer = product.id === "cv" || product.id === "hv";

  const totalH = shellLength + 2 * headDepthID;
  const scaleX = 300 / (D_ID + 80);
  const scaleY = 440 / (totalH + 80);
  const scale = Math.min(scaleX, scaleY);
  const sw = D_ID * scale;
  const sh = shellLength * scale;
  const hd = headDepthID * scale;
  const cx = 200, topY = 50;
  const shellTop = topY + hd;
  const shellBot = shellTop + sh;
  const botY = shellBot + hd;

  const acceptVol = sizing?.expandedWater || sizing?.acceptanceVolGal || 0;
  const totalVol = vessel.actualVolGal || 1;
  const bladderFrac = product.internals === "none" ? 0.85 :
    product.internals === "full-bladder" ? 0.85 :
    product.internals === "partial-bladder" ? 0.55 :
    Math.min(0.7, Math.max(0.3, acceptVol / totalVol + 0.15));

  const iColors = {
    "diaphragm": "#E8D44D",
    "full-bladder": "#5DADE2",
    "partial-bladder": "#48C9B0",
    "none": "transparent",
  };
  const ic = iColors[product.internals];

  // Schematic head depth follows the selected geometry. Knuckle contours and cap straight flanges require supplier drawings.
  const headCurve = topY;

  return (
    <svg viewBox="0 0 400 560" className="w-full h-full" style={{ maxHeight: 500 }}>
      <defs>
        <linearGradient id="sg" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stopColor="#4A4A4A" /><stop offset="25%" stopColor="#6A6A6A" />
          <stop offset="45%" stopColor="#8A8A8A" /><stop offset="55%" stopColor="#9A9A9A" />
          <stop offset="75%" stopColor="#7A7A7A" /><stop offset="100%" stopColor="#4A4A4A" />
        </linearGradient>
        <linearGradient id="ag" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#AED6F1" stopOpacity="0.2" />
          <stop offset="100%" stopColor="#AED6F1" stopOpacity="0.05" />
        </linearGradient>
        <linearGradient id="wg" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#2E86C1" stopOpacity="0.25" />
          <stop offset="100%" stopColor="#1B4F72" stopOpacity="0.35" />
        </linearGradient>
        <filter id="glow"><feGaussianBlur stdDeviation="2" result="g"/>
          <feMerge><feMergeNode in="g"/><feMergeNode in="SourceGraphic"/></feMerge>
        </filter>
      </defs>

      {/* === VESSEL BODY === */}
      {/* Top Head */}
      <path d={`M ${cx - sw/2} ${shellTop} Q ${cx - sw/2} ${headCurve}, ${cx} ${topY} Q ${cx + sw/2} ${headCurve}, ${cx + sw/2} ${shellTop}`}
        fill="url(#sg)" stroke="#2C2C2C" strokeWidth="2.5" />
      {/* Shell */}
      <rect x={cx - sw/2} y={shellTop} width={sw} height={sh} fill="url(#sg)" stroke="#2C2C2C" strokeWidth="2.5" />
      {/* Bottom Head */}
      <path d={`M ${cx - sw/2} ${shellBot} Q ${cx - sw/2} ${botY}, ${cx} ${botY} Q ${cx + sw/2} ${botY}, ${cx + sw/2} ${shellBot}`}
        fill="url(#sg)" stroke="#2C2C2C" strokeWidth="2.5" />

      {/* === INTERNALS === */}
      {product.internals !== "none" && (
        <>
          {/* Air cushion (top) */}
          <rect x={cx - sw/2 + 8} y={shellTop + 4} width={sw - 16}
            height={(sh) * (1 - bladderFrac) - 4} fill="url(#ag)" rx="3" />
          <text x={cx} y={shellTop + (sh) * (1 - bladderFrac) / 2 + 2}
            textAnchor="middle" fill="#85C1E9" fontSize="8" fontWeight="700" letterSpacing="1">
            PRE-CHARGED AIR
          </text>

          {/* Diaphragm line */}
          {product.internals === "diaphragm" && (
            <>
              <path d={`M ${cx - sw/2 + 5} ${shellTop + sh * (1 - bladderFrac)} Q ${cx} ${shellTop + sh * (1 - bladderFrac) + 8} ${cx + sw/2 - 5} ${shellTop + sh * (1 - bladderFrac)}`}
                fill="none" stroke={ic} strokeWidth="3" strokeDasharray="8,4" filter="url(#glow)" />
              <text x={cx} y={shellTop + sh * (1 - bladderFrac) - 6}
                textAnchor="middle" fill={ic} fontSize="7.5" fontWeight="800" letterSpacing="1.5">DIAPHRAGM</text>
            </>
          )}

          {/* Bladder outline */}
          {(product.internals === "full-bladder" || product.internals === "partial-bladder") && (
            <>
              <rect x={cx - sw/2 + 12} y={shellTop + sh * (1 - bladderFrac) + 4}
                width={sw - 24} height={sh * bladderFrac + hd - 12}
                fill="none" stroke={ic} strokeWidth="2.5" strokeDasharray="6,3" rx="6" filter="url(#glow)" />
              <text x={cx} y={shellTop + sh * (1 - bladderFrac / 2) + 4}
                textAnchor="middle" fill={ic} fontSize="7.5" fontWeight="800" letterSpacing="1.5">
                {product.internals === "full-bladder" ? "REPLACEABLE BLADDER" : "PARTIAL BLADDER"}
              </text>
            </>
          )}

          {/* Water in the bottom */}
          <rect x={cx - sw/2 + (product.internals === "diaphragm" ? 8 : 14)}
            y={shellTop + sh * (1 - bladderFrac) + (product.internals === "diaphragm" ? 6 : 6)}
            width={sw - (product.internals === "diaphragm" ? 16 : 28)}
            height={sh * bladderFrac + hd - 14}
            fill="url(#wg)" rx="3" />
          <text x={cx} y={shellBot + hd/2 - 2}
            textAnchor="middle" fill="#5DADE2" fontSize="7" fontWeight="600" opacity="0.8">
            SYSTEM WATER
          </text>
        </>
      )}

      {/* Buffer tank: full of water */}
      {product.internals === "none" && (
        <>
          <rect x={cx - sw/2 + 8} y={shellTop + 6} width={sw - 16} height={sh - 12}
            fill="url(#wg)" rx="3" />
          <text x={cx} y={(shellTop + shellBot) / 2}
            textAnchor="middle" fill="#5DADE2" fontSize="9" fontWeight="700" letterSpacing="1">
            SYSTEM WATER
          </text>
        </>
      )}

      {/* === NOZZLES === */}
      {nozzles.map((n, ni) => {
        // Bladder flange: draw as a wide flanged bottom
        if (n.service === "bladder-flange") {
          const flgW = Math.min(sw * 0.95, (n.blFlangeSize || 8) / D_ID * sw * 1.1);
          return (
            <g key={n.id}>
              <rect x={cx - flgW/2 - 4} y={topY - 7} width={flgW + 8} height={5}
                fill="#4A4A4A" stroke="#2C2C2C" strokeWidth="1.5" rx="1" />
              <rect x={cx - flgW/2} y={topY - 11} width={flgW} height={4}
                fill="#5A5A5A" stroke="#2C2C2C" strokeWidth="1" rx="1" />
              <text x={cx + flgW/2 + 8} y={topY - 5}
                fontSize="7" fill="#B0B0B0" fontWeight="600" textAnchor="start">{n.id}: Access TBD</text>
            </g>
          );
        }

        const nLen = 18, nThk = Math.max(8, Math.min(14, (n.size || 0.5) * 8));
        let nx, ny, isVert = false, isTop = false;

        // Count nozzles at same position (exclude bladder flange from offset)
        const samePos = nozzles.filter(nn => nn.position === n.position && nn.service !== "bladder-flange");
        const posIdx = samePos.indexOf(n);
        const offset = samePos.length > 1 ? (posIdx - (samePos.length - 1) / 2) * 22 : 0;

        if (n.position === "top-head") { nx = cx + offset; ny = topY; isVert = true; isTop = true; }
        else if (n.position === "bottom-head") { nx = cx + offset; ny = botY; isVert = true; }
        else if (n.position === "bottom-side") { nx = cx + sw/2; ny = shellBot - 6; }
        else if (n.position === "top-side") { nx = cx + sw/2; ny = shellTop + 15; }
        else { nx = cx + sw/2; ny = (shellTop + shellBot) / 2; }

        return (
          <g key={n.id}>
            {isVert ? (
              <>
                <rect x={nx - nThk/2} y={isTop ? ny - nLen : ny}
                  width={nThk} height={nLen} fill="#5A5A5A" stroke="#2C2C2C" strokeWidth="1.5" rx="1.5" />
                <rect x={nx - nThk/2 - 3} y={isTop ? ny - nLen - 3 : ny + nLen}
                  width={nThk + 6} height={4} fill="#4A4A4A" stroke="#2C2C2C" strokeWidth="1" rx="1" />
              </>
            ) : (
              <>
                <rect x={nx} y={ny - nThk/2} width={nLen} height={nThk}
                  fill="#5A5A5A" stroke="#2C2C2C" strokeWidth="1.5" rx="1.5" />
                <rect x={nx + nLen} y={ny - nThk/2 - 3} width={4} height={nThk + 6}
                  fill="#4A4A4A" stroke="#2C2C2C" strokeWidth="1" rx="1" />
              </>
            )}
            <text x={isVert ? nx + nThk/2 + 6 : nx + nLen + 10}
              y={isVert ? (isTop ? ny - nLen + 6 : ny + nLen) : ny + 3}
              fontSize="7.5" fill="#B0B0B0" fontWeight="600">{n.label2 || n.label}</text>
            <text x={isVert ? nx + nThk/2 + 6 : nx + nLen + 10}
              y={isVert ? (isTop ? ny - nLen + 15 : ny + nLen + 9) : ny + 12}
              fontSize="6.5" fill="#888" fontWeight="500">
              {n.id}: {n.size >= 1 && !n.label.includes("Schrader") ? n.label : (n.label.includes("Schrader") ? "Schrader" : n.label)}
            </text>
          </g>
        );
      })}

      {/* === DIMENSION ANNOTATIONS === */}
      {/* OAL */}
      <line x1={cx - sw/2 - 28} y1={topY} x2={cx - sw/2 - 28} y2={botY}
        stroke="#D4A017" strokeWidth="0.8" />
      <line x1={cx - sw/2 - 34} y1={topY} x2={cx - sw/2 - 22} y2={topY} stroke="#D4A017" strokeWidth="0.5" />
      <line x1={cx - sw/2 - 34} y1={botY} x2={cx - sw/2 - 22} y2={botY} stroke="#D4A017" strokeWidth="0.5" />
      <text x={cx - sw/2 - 32} y={(topY + botY) / 2 - 4} fontSize="7.5" fill="#D4A017"
        fontWeight="700" textAnchor="end" transform={`rotate(-90, ${cx - sw/2 - 32}, ${(topY + botY) / 2})`}>
        {vessel.OAL.toFixed(2)}" BODY
      </text>

      {/* Diameter */}
      <line x1={cx - sw/2} y1={botY + 28} x2={cx + sw/2} y2={botY + 28} stroke="#D4A017" strokeWidth="0.8" />
      <line x1={cx - sw/2} y1={botY + 22} x2={cx - sw/2} y2={botY + 34} stroke="#D4A017" strokeWidth="0.5" />
      <line x1={cx + sw/2} y1={botY + 22} x2={cx + sw/2} y2={botY + 34} stroke="#D4A017" strokeWidth="0.5" />
      <text x={cx} y={botY + 42} fontSize="8" fill="#D4A017" textAnchor="middle" fontWeight="700">
        {vessel.D_ID.toFixed(3)}" ID / {vessel.D_OD.toFixed(3)}" OD
      </text>

      {/* Construction type label */}
      <text x={cx} y={botY + 56} fontSize="7" fill="#888" textAnchor="middle" fontWeight="500">
        {vessel.constructionType}
      </text>
      <text x={cx} y={botY + 66} fontSize="7" fill="#888" textAnchor="middle" fontWeight="500">
        {vessel.headType}
      </text>

      {/* Shell thickness callout */}
      <text x={cx + sw/2 + 8} y={(shellTop + shellBot) / 2}
        fontSize="7" fill="#999" fontWeight="500"
        transform={`rotate(90, ${cx + sw/2 + 8}, ${(shellTop + shellBot) / 2})`}
        textAnchor="middle">
        t(shell) = {vessel.tShell}"
      </text>

      {/* Support: Skirt or Clips */}
      {vessel.actualVolGal > 5 && supportType === "skirt" && (
        <>
          {/* Skirt cylinder */}
          <rect x={cx - sw/2} y={botY} width={sw} height={hd * 0.8 + 12}
            fill="none" stroke="#555" strokeWidth="2" rx="0" />
          <rect x={cx - sw/2 + 1} y={botY + 1} width={sw - 2} height={hd * 0.8 + 10}
            fill="#2A2A2A" rx="0" />
          {/* Mouse holes (openings) — 2 shown as cutouts at bottom of skirt */}
          <rect x={cx - sw * 0.12} y={botY + hd * 0.4 + 6} width={sw * 0.24} height={hd * 0.4 + 5}
            fill="#0D0D18" stroke="#444" strokeWidth="0.8" rx="2" />
          {/* Base ring */}
          <rect x={cx - sw/2 - 4} y={botY + hd * 0.8 + 10} width={sw + 8} height={4}
            fill="#4A4A4A" stroke="#333" strokeWidth="1.5" rx="1" />
          <text x={cx} y={botY + hd * 0.5 + 4} textAnchor="middle" fill="#666" fontSize="6.5" fontWeight="600">SKIRT</text>
        </>
      )}
      {vessel.actualVolGal > 5 && supportType === "clips" && (
        <>
          {/* Mounting clips — L-brackets on sides */}
          {[-1, 1].map(side => (
            <g key={side}>
              <rect x={cx + side * (sw/2 - 2) - (side > 0 ? 0 : 12)} y={botY - 4}
                width={12} height={20} fill="#4A4A4A" stroke="#333" strokeWidth="1" rx="1" />
              <rect x={cx + side * (sw/2 + 2) - (side > 0 ? 0 : 16)} y={botY + 14}
                width={16} height={4} fill="#555" stroke="#333" strokeWidth="1" rx="1" />
              {/* Bolt holes */}
              <circle cx={cx + side * (sw/2 + 6)} cy={botY + 16} r="1.5" fill="#222" stroke="#555" strokeWidth="0.5" />
            </g>
          ))}
        </>
      )}
      <text x="200" y="548" textAnchor="middle" fill="#B8860B" fontSize="8">SCHEMATIC ONLY. INTERNALS AND SUPPORTS REQUIRE DESIGN.</text>
    </svg>
  );
}

const format = (value, digits = 3) => Number.isFinite(value) ? value.toFixed(digits) : 'Not evaluated';

function Field({ label, value, onChange, unit, hint, text = false }) {
  const id = useId();
  return <div className="field"><label htmlFor={id}>{label}{unit && <span> ({unit})</span>}</label>
    <input id={id} type={text ? 'text' : 'number'} step="any" value={value ?? ''} onChange={e => onChange(e.target.value)} />
    {hint && <small>{hint}</small>}</div>;
}
function Row({label, children}) { return <div className="spec-row"><span>{label}</span><b>{children}</b></div>; }
function Section({title, children}) { return <section><h3>{title}</h3>{children}</section>; }

export default function App() {
  const [selProduct,setSelProduct] = useState(null);
  const [inputs,setInputs] = useState({...DEFAULT_INPUTS});
  const [materialId,setMaterialId] = useState('CS');
  const [CA,setCA] = useState(0.0625);
  const [sizingMode,setSizingMode] = useState('tank');
  const [tankVol,setTankVol] = useState('');
  const [tankVolUnit,setTankVolUnit] = useState('gal');
  const [supportType,setSupportType] = useState('skirt');
  const [reportHTML,setReportHTML] = useState('');
  const [quoteOpen,setQuoteOpen] = useState(false);
  const [quoteSession,setQuoteSession] = useState(newSession);
  const [quoteLoadError,setQuoteLoadError] = useState('');
  const product = PRODUCTS.find(p => p.id === selProduct);
  const isBuffer = product?.internals === 'none';
  const state = useMemo(() => evaluateDesign({product,inputs,sizingMode,tankVol,materialId,CA,supportType}),
    [product,inputs,sizingMode,tankVol,materialId,CA,supportType]);
  const {vessel:v,sizing,error,effectiveTankVol} = state;
  const update = (key,value) => setInputs(prev => ({...prev,[key]:value,
    ...(key === 'designTemp' || key === 'codeEdition' ? {shellStress:'',pipeStress:'',headStress:'',nozzleStress:'',stressBasis:''} : {})}));
  const field = (key,label,unit,hint,text = false) => <Field key={key} label={label} value={inputs[key]} onChange={value => update(key,value)} unit={unit} hint={hint} text={text} />;
  const reset = () => { setSelProduct(null); setInputs({...DEFAULT_INPUTS}); setMaterialId('CS'); setCA(0.0625);
    setSizingMode('tank'); setTankVol(''); setTankVolUnit('gal'); setSupportType('skirt'); setReportHTML(''); setQuoteOpen(false); setQuoteSession(newSession()); };
  const restoreQuoteDesign = d => {
    const nextProduct=PRODUCTS.find(p=>p.id===d.productId);
    if (!nextProduct || !d.inputs || !['CS','SS304','SS316'].includes(d.materialId) || !['skirt','clips'].includes(d.supportType)) throw new Error('The quote project has an invalid design basis.');
    for(const [key,value] of Object.entries(d.inputs)) if(!(key in DEFAULT_INPUTS)||!['string','number'].includes(typeof value)) throw new Error(`Invalid design input: ${key}`);
    const checked=evaluateDesign({...d,product:nextProduct});
    if(checked.error || !checked.vessel) throw new Error(checked.error || 'The quote project needs a valid vessel design.');
    setSelProduct(d.productId);setInputs({...DEFAULT_INPUTS,...d.inputs});setSizingMode(d.sizingMode);setTankVol(d.tankVol);setTankVolUnit('gal');setMaterialId(d.materialId);setCA(d.CA);setSupportType(d.supportType);
  };
  const openQuoteProject = async event => {
    const file=event.target.files[0];event.target.value='';if(!file)return;
    try {if(file.size>12e6)throw new Error('Project exceeds 12 MB.');const saved=loadProject(await file.text());restoreQuoteDesign(saved.design);setQuoteSession(saved.session);setQuoteLoadError('');setQuoteOpen(true);}
    catch(e){setQuoteLoadError(e.message);}
  };
  const report = () => {
    if (!v || error) return;
    const diagram = renderToStaticMarkup(<VesselSVG vessel={v} product={product} sizing={sizing} supportType={supportType} />);
    setReportHTML(generateReportHTML(product,inputs,sizing,v,JWT_LOGO,diagram));
  };
  if (reportHTML) return <div style={{height:'100vh',display:'flex',flexDirection:'column',background:'#e8e8e8'}}>
    <div style={{padding:12,display:'flex',gap:12}}><button onClick={() => setReportHTML('')}>Back to design</button>
      <button onClick={() => { const frame = document.getElementById('report-preview'); frame?.contentWindow?.print(); }}>Print / Save PDF</button></div>
    <iframe id="report-preview" title="Engineering calculation report" srcDoc={reportHTML} sandbox="allow-same-origin allow-modals" style={{border:0,width:'100%',flex:1}} />
  </div>;
  return <div className="jwt-app"><style>{`
    *{box-sizing:border-box}.jwt-app{background:#0D0D16;min-height:100vh;color:#E0DAD0;font-family:Aptos,'Segoe UI',sans-serif}
    .jwt-app button{cursor:pointer;font-family:inherit}.jwt-app button:disabled{opacity:.4;cursor:not-allowed}
    .jwt-header{display:flex;align-items:center;justify-content:space-between;gap:20px;background:#08080E;border-bottom:1px solid #B8860B44;padding:16px 24px}
    .jwt-header img{height:34px}.jwt-header strong{color:#B8860B;letter-spacing:2px}.jwt-app h1{font-size:26px}.jwt-app h2{font-size:17px}.jwt-app h3{font-size:11px;color:#B8860B;letter-spacing:1.5px;margin:0 0 14px;text-transform:uppercase}
    .jwt-app section{border-bottom:1px solid #262635;padding:18px 0}.field{margin-bottom:14px}.field label{display:block;font-size:11px;color:#A4A4B8;margin-bottom:5px;font-weight:600}
    .field input,.jwt-app select{width:100%;background:#16162A;border:1px solid #383849;border-radius:5px;color:#F0E6D3;padding:8px 10px;font-size:13px}
    .field input:focus{outline:1px solid #B8860B}.field small{display:block;color:#8E8EA3;font-size:10px;line-height:1.5;margin-top:4px}
    .jwt-columns{display:grid;grid-template-columns:340px minmax(300px,1fr) 300px;gap:0}.jwt-inputs,.jwt-specs{padding:0 20px 32px;background:#10101A}
    .jwt-specs{border-left:1px solid #262635}.jwt-inputs{border-right:1px solid #262635}.jwt-visual{padding:24px;position:sticky;top:0;align-self:start;min-width:0;text-align:center}
    .jwt-visual svg{width:100%;max-height:600px}.jwt-visual .badge{color:#B8860B;font-size:21px;font-weight:800;letter-spacing:2px;margin:20px 0 5px}
    .toggle{display:flex;margin:8px 0 16px;gap:6px}.toggle button,.secondary{background:#1A1A2A;border:1px solid #383849;color:#A4A4B8;padding:8px;border-radius:4px;font-size:11px}
    .toggle button{flex:1}.toggle button.active{background:#B8860B;color:#0D0D16;border-color:#B8860B;font-weight:bold}
    .spec-row{display:flex;justify-content:space-between;gap:10px;padding:6px 0;font-size:11px;line-height:1.5}.spec-row span{color:#8E8EA3}.spec-row b{text-align:right;max-width:65%;overflow-wrap:anywhere}
    .notice{background:#191926;border:1px solid #B8860B55;border-radius:6px;padding:14px;color:#C8BD9C;font-size:12px;line-height:1.6;margin:18px 0;text-align:left}
    .status{color:#D4A017;font-size:12px;line-height:1.6}.jwt-actions{display:flex;justify-content:space-between;gap:15px;padding:16px 24px;background:#08080E;border-top:1px solid #B8860B44}
    .primary{background:linear-gradient(135deg,#8B6914,#D4A017);border:0;border-radius:5px;padding:12px 24px;font-weight:bold;color:#0D0D16}
    .products{max-width:1200px;margin:auto;padding:40px 24px}.product-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.product-card{text-align:left;background:#141420;border:1px solid #353548;border-radius:8px;color:#E0DAD0;padding:22px}
    .product-card p{font-size:12px;line-height:1.7;color:#9999AF}.product-card:hover{border-color:#B8860B}.jwt-app details{font-size:12px;line-height:1.8;color:#A4A4B8}.jwt-app summary{cursor:pointer;color:#B8860B}
    @media(max-width:1000px){.jwt-columns{grid-template-columns:320px 1fr}.jwt-specs{grid-column:1/-1}.product-grid{grid-template-columns:repeat(2,1fr)}}
    @media(max-width:640px){.jwt-columns,.product-grid{display:block}.jwt-visual{position:static}.jwt-header{padding:12px}.jwt-header strong{font-size:12px}.product-card{margin-bottom:16px}.jwt-specs{border-left:0}}
  `}</style>
    <header className="jwt-header"><img src={JWT_LOGO} alt="JWT" /><strong>TANK DESIGNER, SIZER &amp; QUOTING</strong>{product && <button className="secondary" onClick={reset}>Products / Reset</button>}</header>
    {!product ? <main className="products"><h1>Select a product line</h1><p>Water expansion, buffer energy sizing and prelim ASME vessel sizing.</p>
      <p><button className="secondary" onClick={()=>document.getElementById('open-quote-project').click()}>Open saved quote project</button><input hidden id="open-quote-project" type="file" accept=".json" onChange={openQuoteProject}/></p>
      {quoteLoadError&&<div className="notice" role="alert">{quoteLoadError}</div>}
      <div className="notice">Calculations require a project pressure/temperature basis. Prelim supplies preliminary material curves and mechanical sizing, or you can enter verified allowable stresses. Schematics and component selections remain preliminary until the outstanding vessel checks are completed. Fluid model: pure liquid water.</div>
      <div className="product-grid">{PRODUCTS.map(p => <button className="product-card" key={p.id} onClick={() => {setSelProduct(p.id);setInputs({...DEFAULT_INPUTS,mawp:p.defaultMawp});}}>
        <h2 style={{color:p.color}}>{p.name}</h2><b>{p.subtitle}</b><p>{p.desc}</p><small>{p.internals === 'none' ? 'Energy balance or direct volume' : 'Pressure and membrane acceptance sizing'}</small>
      </button>)}</div></main> : <>
      <div className="jwt-columns"><aside className="jwt-inputs">
        <Section title="Product and material"><h2 style={{color:product.color}}>{product.name}</h2>
          <label className="field">Material<select aria-label="Material" value={materialId} onChange={e => {setMaterialId(e.target.value);setInputs(prev => ({...prev,shellStress:'',pipeStress:'',headStress:'',nozzleStress:'',stressBasis:''}));}}>
            {Object.values(MATERIALS).map(m => <option key={m.id} value={m.id}>{m.label}</option>)}</select></label>
          <div className="toggle">{[0,0.0625,0.125].map(c => <button key={c} className={CA === c ? 'active' : ''} onClick={() => setCA(c)}>CA {c}"</button>)}</div>
          <label className="field">Support concept<select aria-label="Support concept" value={supportType} onChange={e => setSupportType(e.target.value)}><option value="skirt">Skirt</option><option value="clips">Mounting clips</option></select></label>
        </Section>
        <Section title="Thermal sizing method"><div className="toggle"><button className={sizingMode === 'tank' ? 'active' : ''} onClick={() => setSizingMode('tank')}>Direct volume</button><button className={sizingMode === 'system' ? 'active' : ''} onClick={() => setSizingMode('system')}>{isBuffer ? 'Energy balance' : 'Size for system'}</button></div>
          {sizingMode === 'tank' ? <><Field label="Required tank volume" value={tankVol === '' ? '' : Number(tankVol)*(tankVolUnit === 'L' ? 3.785411784 : 1)} unit={tankVolUnit} onChange={value => setTankVol(value === '' ? '' : Number(value)/(tankVolUnit === 'L' ? 3.785411784 : 1))} />
            <div className="toggle">{['gal','L'].map(u => <button key={u} className={tankVolUnit === u ? 'active' : ''} onClick={() => setTankVolUnit(u)}>{u === 'gal' ? 'US gallons' : 'Litres'}</button>)}</div><small>Direct volume does not verify system thermal capacity.</small></> : isBuffer ? <>
            {field('sourceOutput','Minimum stable source output','Btu/hr','Use the active chiller or boiler stage, as a positive magnitude.')}
            {field('minimumLoad','Coincident minimum load','Btu/hr')}{field('runtimeMin','Minimum source run time','min')}
            {field('bufferLowTemp','Lower tank control temperature','°F')}{field('bufferHighTemp','Upper tank control temperature','°F','Use the control deadband, not the supply/return design difference.')}
            {field('existingVolume','Existing active system volume','US gal')}{field('utilizationPercent','Usable buffer volume','%','100% assumes the full tank participates in the cycle.')}
          </> : <>
            {field('systemVol',product.potable ? 'Heated water system volume' : 'System water volume','US gal','Volume at the minimum-temperature endpoint, including active components.')}
            {field('fillTemp','Minimum fluid temperature','°F','Use the coldest liquid state. The water-density maximum is included if crossed.')}
            {field('precharge','Actual empty-tank precharge','psig','At the tank datum. Set with no water pressure on the tank.')}
            {field('acceptancePercent','Supplier maximum water acceptance','% of tank','Required for diaphragm, partial and full bladder designs. Use supplier maximum acceptance volume divided by nominal tank volume.')}
            {field('gasExponent','Gas polytropic exponent','n','1 is isothermal. Values up to 1.4 can screen faster compression.')}
          </>}
          {sizing && <div className="notice"><b>Thermal result</b>{sizing.kind === 'expansion' && <><Row label="Expanded water">{format(sizing.expandedWater)} gal</Row><Row label="Usable acceptance">{format(sizing.acceptanceFactor,5)}</Row></>}
            <Row label="Minimum tank volume">{format(sizing.minTankVol)} gal</Row><Row label="Selected with 5% allowance">{effectiveTankVol} gal</Row>
            {effectiveTankVol === 0 && <p>No additional buffer volume is required by this cycling case.</p>}</div>}
        </Section>
        <Section title="Operating and pressure basis">
          {field('operatingTemp','Maximum fluid temperature','°F','Include chilled-loop shutdown warm-up. Pure water only.')}
          {field('designTemp','Design metal temperature','°F','Must cover the fluid temperature. Changing it clears allowable stresses.')}
          {field('minPressure','Minimum operating pressure at tank','psig')}{field('maxPressure','Maximum operating pressure at tank','psig')}
          {field('reliefPressure','Relief set pressure at tank datum','psig')}{field('reliefMargin','Operating margin below relief','psi')}
          {field('mawp','Top design pressure','psig','Design input. Vessel MAWP is a separate result requiring all component checks.')}
          {field('atmosphericPsia','Site atmospheric pressure','psia')}
        </Section>
        <Section title="ASME calculation basis">
          {field('codeEdition','Project ASME code edition',null,'Use the edition adopted for this project.',true)}
          <label className="field">Mechanical sizing method<select aria-label="Mechanical sizing method" value={inputs.mechanicalMethod} onChange={e=>update('mechanicalMethod',e.target.value)}><option value="prelim">Prelim engine and code assessment</option><option value="entered">Entered stress, pressure-wall method</option></select></label>
          {inputs.mechanicalMethod === 'prelim' ? <PrelimControls inputs={inputs} update={update} field={field} /> : <>
          <small>Enter Section II-D stresses at the design metal temperature for the exact material, product form, thickness and table notes. The app contains no licensed allowable-stress database.</small>
          {field('shellStress','Plate-shell allowable stress','psi','Used when the selected shell is rolled plate.')}
          {field('pipeStress','Seamless pipe-shell allowable stress','psi','Used when the selected shell is standard pipe.')}
          {field('headStress','Formed-head allowable stress','psi')}{field('nozzleStress','Seamless nozzle-pipe allowable stress','psi')}
          {field('stressBasis','Allowable-stress table / row / notes',null,'Identify shell pipe or plate, head plate and nozzle pipe. Confirm the resulting construction matches this basis.',true)}
          {field('shellE','Rolled-shell longitudinal joint efficiency','E','Pipe shells are explicitly seamless. Verify joint category and examination.')}
          {field('circumferentialE','Shell circumferential joint efficiency','E')}{field('headE','Head joint efficiency','E','Enter from the applicable head construction and examination rules.')}
          {field('plateTolerance','Plate thickness deduction','in','Conservative manufacturing allowance. Verify the ordered material basis.')}
          {field('headFormingPercent','Head forming-loss allowance','%','Planning allowance. The supplier must guarantee the required minimum formed thickness.')}
          </>}
        </Section>
        <Section title="Nozzle flow basis">{isBuffer ? field('designFlowGPM','Actual buffer design flow','GPM') : field('expansionFlowGPM','Peak expansion connection flow','GPM','0 leaves port flow unverified. Total expansion / heat-up time is an average, not a peak.')}
          {field('velocityLimit','Project nozzle velocity target','ft/s','Default is a screening target. Check the project hydraulic requirements.')}
        </Section>
        <details><summary>How this product works</summary>{product.howItWorks.split('\n\n').map((p,i) => <p key={i}>{p}</p>)}</details>
      </aside>
      <main className="jwt-visual"><div className="badge">{v ? `${product.prefix}-${Math.round(v.actualVolGal)}` : product.prefix}</div><small>{product.subtitle}</small>
        {error && <div className="notice" role="alert">{error}</div>}
        {v ? <><VesselSVG vessel={v} product={product} sizing={sizing} supportType={supportType} /><div className="notice">Shell and head sizing meets the selected preliminary basis, subject to the specified minimum delivered thickness. Complete vessel MAWP and fabrication checks remain open.</div></> : <p className="status">Enter the required design basis to calculate the vessel.</p>}
      </main>
      <aside className="jwt-specs">{v && <>
        <Section title="Dimensions"><Row label="Geometric volume">{format(v.actualVolGal)} gal</Row><Row label="Construction">{v.constructionType}</Row><Row label="Heads">{v.headType}</Row><Row label="ID / OD">{format(v.D_ID)} / {format(v.D_OD)} in</Row><Row label="Shell length">{format(v.shellLength)} in</Row><Row label="Body length">{format(v.OAL)} in</Row></Section>
        <Section title="Pressure-wall results"><Row label="Shell required + CA">{format(v.tShellCalc,5)} in</Row><Row label="Shell nominal / minimum">{format(v.tShell,5)} / {format(v.shellMin,5)} in</Row><Row label="Head required + CA">{format(v.tHeadCalc,5)} in</Row><Row label="Head blank / formed minimum">{format(v.tHead,5)} / {format(v.headMin,5)} in</Row><Row label="Static head allowance">{format(v.staticHeadPsi)} psi</Row><Row label="Shell-only pressure capacity">{format(v.shellCapacity)} psig</Row><Row label="Head-only pressure capacity">{format(v.headCapacity)} psig</Row><small>Component capacities are referenced to the vessel top. Vessel MAWP remains unestablished.</small></Section>
        {v.prelim && <PrelimResults prelim={v.prelim} />}
        <Section title="Nozzles">{v.nozzles.map(n => <div key={n.id}><Row label={`${n.id} ${n.label}`}>{n.size > 0 ? `NPS ${n.size}` : 'TBD'}</Row>{n.flow && <Row label="Velocity / port loss">{format(n.flow.v_fps)} ft/s / {format(n.flow.dP_total_psi,5)} psi</Row>}<small>{n.schedule || n.connType}. Rating and reinforcement TBD.</small></div>)}</Section>
        <Section title="Estimated full-water load"><Row label="Support concept">{supportType}</Row><Row label="Empty">{supportType === 'clips' ? v.emptyWeightClips : v.emptyWeight} lb</Row><Row label="Full-water gross">{supportType === 'clips' ? v.operatingWeightClips : v.operatingWeight} lb</Row><small>Includes approximate attachments. Confirm lifting, transport and support loads from final fabrication details.</small></Section>
        <Section title="Outstanding checks">{v.requirements.map(r => <p key={r} style={{fontSize:11,lineHeight:1.7}}>{r}</p>)}</Section>
      </>}</aside></div>
      <footer className="jwt-actions">{v?.prelim && <button className="secondary" onClick={()=>{
        const blob=new Blob([JSON.stringify({product:product.id,inputs,sizing,vessel:v},null,2)],{type:'application/json'});
        const url=URL.createObjectURL(blob),a=document.createElement('a'); a.href=url;a.download='jwt-prelim-design.json';a.click();URL.revokeObjectURL(url);
      }}>Export calculation JSON</button>}<button className="secondary" onClick={reset}>Reset all</button><button className="primary" disabled={!v || !!error} onClick={()=>setQuoteOpen(true)}>Build quote</button><button className="primary" disabled={!v || !!error} onClick={report}>Generate engineering report</button></footer>
      <QuoteWorkbench open={quoteOpen} onClose={()=>setQuoteOpen(false)} vessel={v} product={product} inputs={inputs} session={quoteSession} onChange={setQuoteSession}
        designContext={{productId:product.id,inputs,sizingMode,tankVol,materialId,CA,supportType}} onRestoreDesign={restoreQuoteDesign}/>
    </>}
  </div>;
}
